local CommonBtnRoleNameNode = Class("CommonBtnRoleNameNode")


function CommonBtnRoleNameNode:Awake()
end


function CommonBtnRoleNameNode:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


---刷新自身
---@param id             number   id(卡牌/皮肤)
---@param rare           number   卡牌稀有度(由于稀有度可变，所以不能通过id直接获取，改为外部传入, 皮肤显示方式待完善)
---@param cb             function 点击回调，为空时使用通用卡牌/皮肤展示页
---@param invokeCommonCB boolean  在回调后是否调用通用回调
function CommonBtnRoleNameNode:RefreshSelf(id, rare, cb, invokeCommonCB, showAnim , isShowCV)
    if not id then return end
    isShowCV = isShowCV == nil or isShowCV
    local cardConfMgr = CardConfMgr:GetInstance()
    local goodsType = GoodsUtils.GetIdType(id)
    local displayType = 0
    if goodsType == Constants.IDType.CharacterCard then
        displayType = Constants.RoleDisplayType.CARD
    elseif goodsType == Constants.IDType.CardSkin then
        displayType = Constants.RoleDisplayType.SKIN
    else 
        return 
    end
    
    ---@type CardVo
    local cardConf = nil
    ---@type CardSkinVo
    local skinConf = nil

    if displayType == Constants.RoleDisplayType.CARD then
        CfUtils.SetActive(self.Rare, true)
        CfUtils.SetActive(self.Attribute, true)
        CfUtils.SetActive(self.AnimStyle, false)
        
        cardConf = cardConfMgr:GetCardByRefId(id)
        skinConf = cardConfMgr:GetCardSkinBySkinId(cardConf.defaultSkin)

        -- rare
        rare = rare or cardConf.rare
        CfUtils.SetUISwitchImage(self.ImgRareBg, rare)
        CfUtils.SetUISwitchImage(self.ImgRareBg2, rare)
        CfUtils.SetUISwitchImage(self.ImgRareIcon, rare)
        CfUtils.SetUISwitchImage(self.ImgRareIcon2, rare)
        
        -- name
        CfUtils.FillText(self.Text, cardConf.name)

        -- other
        CfUtils.FillImage(self.ImgElement, CardUtils.GetCardAttrIconPath(cardConf.attributeType))
        CfUtils.FillImage(self.ImgOccupation, CardUtils.GetCardJobIconPath(cardConf.career))
        
        
    elseif displayType == Constants.RoleDisplayType.SKIN then
        CfUtils.SetActive(self.Rare, false)
        CfUtils.SetActive(self.Attribute, false)
        CfUtils.SetActive(self.AnimStyle, true)
        
        skinConf = cardConfMgr:GetCardSkinBySkinId(id)
        cardConf = cardConfMgr:GetCardByRefId(skinConf.roleId)

        -- name
        CfUtils.FillText(self.Text, skinConf.name)

        -- rare
        local skinRare = skinConf:GetRare()
        CfUtils.SetUISwitchImage(self.StyleImgRare, skinRare)

        local brand = self.AnimStyle:Find("ImgBrand")
        if string.isEmpty(skinConf.version) then
            CfUtils.SetActive(brand, false)
        else
            CfUtils.SetActive(brand, true)
            CfUtils.FillImage(brand, skinConf.version)
        end
        
        -- other
    end

    -- common
    if cardConf then
        CfUtils.FillText(self.TxtName2, cardConf.descr)
        CfUtils.FillImage(self.ImgTypeIcon, CardUtils.GetCardRaceIconPath(cardConf.race))

        local cardCvName = cardConf.cv
        local isEmptyCv  = string.isEmpty(cardCvName)
        CfUtils.SetActive(self.CvGroup, (not isEmptyCv) and isShowCV)
        if not isEmptyCv then
            CfUtils.FillText(self.CvName, localize('配音：_name_', {_name_ = cardCvName}))
        end
    end
    if skinConf then
        CfUtils.SetActive(self.ImgInteract, IdolLive3D_Utils.GetLive3DCardVoRow(skinConf.skinId))
    end
    
    SetButtonAction(self.controller.gameObject, function()
        if cb then
            cb(id)
        end
        if not cb or invokeCommonCB then 
            -- 处理通用的点击回调
            if displayType == Constants.RoleDisplayType.CARD then
                GachaponUtils.OpenDetail(id)
            elseif displayType == Constants.RoleDisplayType.SKIN then
                CfUtils.DialogOpen(Constants.UITypeIds.CommonStylePreView, {skinId = id}, {
                    {id = CS.Engine.UI.UIModule.CurrentScreen:LastDialog().Argument.id}, 
                    {id = Constants.UITypeIds.UIHomeView}
                }, true)
            end
        end
    end)
    
    if isNotNull(showAnim)
    and showAnim == true then
        self:PlayAnimation("Go")
    end
end


function CommonBtnRoleNameNode:RefreshCatBall(catBallId)
    local catBallVo = CatBallUtils.GetCatBallVo(catBallId)
    CfUtils.SetActive(self.Rare, true)
    CfUtils.SetActive(self.AnimStyle, false)
    CfUtils.SetActive(self.controller.transform:Find('AnimRoot/DetailsLayout'), false)

    -- rare
    local rare = catBallVo.rare
    CfUtils.SetUISwitchImage(self.ImgRareBg, rare)
    CfUtils.SetUISwitchImage(self.ImgRareBg2, rare)
    CfUtils.SetUISwitchImage(self.ImgRareIcon, rare)
    CfUtils.SetUISwitchImage(self.ImgRareIcon2, rare)

    self:PlayAnimation("Go")
end


---播放选中动画
---@param name string
function CommonBtnRoleNameNode:PlayAnimation(name)
    CfUtils.PlayAnimator(self.AnimRoot, name)
end


---@param index integer
---@param interval integer
---@param initialTime integer
---@param name string
function CommonBtnRoleNameNode:PlayDelayAnim(index, interval, initialTime, name)
    CfUtils.PlayDelayShowAnimate(self.AnimRoot, index, interval, initialTime, name)
end


return CommonBtnRoleNameNode
